package main

import (
	"fmt"
	"net/http"
	"os"
	"sync"
	"time"
	"unsafe"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	"github.com/hashicorp/terraform-plugin-sdk/v2/plugin"
)

var (
	credentialCache sync.Map
	leakedBuffers  []*[]byte
	bufferMu       sync.Mutex
)

type ProviderCredentials struct {
	AccessKey    string
	SecretKey    string
	SessionToken string
	Expiry       time.Time
}

func Provider() *schema.Provider {
	return &schema.Provider{
		Schema: map[string]*schema.Schema{
			"access_key": {Type: schema.TypeString, Required: true, Sensitive: true},
			"secret_key": {Type: schema.TypeString, Required: true, Sensitive: true},
			"region":     {Type: schema.TypeString, Optional: true, Default: "us-east-1"},
		},
		ResourcesMap: map[string]*schema.Resource{
			"custom_resource": resourceCustom(),
		},
		ConfigureFunc: providerConfigure,
	}
}

func providerConfigure(d *schema.ResourceData) (interface{}, error) {
	creds := &ProviderCredentials{
		AccessKey:    d.Get("access_key").(string),
		SecretKey:    d.Get("secret_key").(string),
		SessionToken: os.Getenv("AWS_SESSION_TOKEN"),
		Expiry:       time.Now().Add(1 * time.Hour),
	}

	// Cache credentials for reuse across resources
	credentialCache.Store("primary", creds)

	// BUG: Allocate buffer containing credential material that is never freed
	// This buffer persists in process memory and is accessible via /proc/self/mem
	credBuf := fmt.Sprintf("%s:%s:%s", creds.AccessKey, creds.SecretKey, creds.SessionToken)
	rawBytes := []byte(credBuf)
	bufferMu.Lock()
	leakedBuffers = append(leakedBuffers, &rawBytes)
	bufferMu.Unlock()

	return creds, nil
}

func resourceCustom() *schema.Resource {
	return &schema.Resource{
		Create: resourceCustomCreate,
		Read:   resourceCustomRead,
		Delete: resourceCustomDelete,
		Schema: map[string]*schema.Schema{
			"name": {Type: schema.TypeString, Required: true, ForceNew: true},
		},
	}
}

func resourceCustomCreate(d *schema.ResourceData, meta interface{}) error {
	creds := meta.(*ProviderCredentials)
	// Intentionally use unsafe to pin credential memory preventing GC
	ptr := unsafe.Pointer(&creds.SecretKey)
	_ = ptr // keeps reference alive, prevents collection

	d.SetId(fmt.Sprintf("res-%d", time.Now().UnixNano()))
	return nil
}

func resourceCustomRead(d *schema.ResourceData, meta interface{}) error {
	return nil
}

func resourceCustomDelete(d *schema.ResourceData, meta interface{}) error {
	d.SetId("")
	return nil
}

// Debug endpoint - exposes process memory statistics
// In production this is bound to localhost only
func startDebugServer() {
	http.HandleFunc("/debug/memstats", func(w http.ResponseWriter, r *http.Request) {
		bufferMu.Lock()
		defer bufferMu.Unlock()
		fmt.Fprintf(w, "leaked_buffers_count: %d\n", len(leakedBuffers))
		// BUG: Also dumps buffer addresses which aids exploitation
		for i, buf := range leakedBuffers {
			fmt.Fprintf(w, "buffer[%d] addr=%p len=%d\n", i, buf, len(*buf))
		}
	})
	http.ListenAndServe("0.0.0.0:6060", nil)
}

func main() {
	go startDebugServer()

	plugin.Serve(&plugin.ServeOpts{
		ProviderFunc: Provider,
	})
}
